head.script:
// =============================================================================
/**
 * 업무 화면 VALIDATE 관련 함수
 *
 * @author Inswave Systems
 * @class validate
 * @namespace $c.validate
 */
// =============================================================================
scwin.onpageload = function() {

};


/**
 * @method
 * @name validateDataCollect
 * @description DataCollection 유효성을 검증하는 공통함수 *
 * @param {Object} validateObj 검증할 component 컨테이너 또는 gridView Component (id 문자열 허용)
 * @param {Object} options 통합 옵션 객체
 *   { 
 * 		validateType:"alert", 
 * 		checkType:"single", 
 * 		focus:true, 
 * 		editMode:true,
 *      fields: { 
 * 			"컴포넌트ID(GridView는 컬럼ID)": { required:true, maxLength:15, ... } 
 * 		} 
 * }
 *   - 동작: validateType(alert|mark|all), checkType(single|multi), focus, editMode
 *   - fields: 필드별 검증 규칙 (값은 객체 형태)
 * @memberOf validate
 * @author WebSquare
 * @return {Boolean} 유효성 검증 결과 (모두 통과 시 true, 실패 시 false)
 * @hidden N
 * @exception
 * @example
    // 전체 옵션 예시 — 동작 옵션 4종 + 규칙 종류별 지정 예
    const options = {
        validateType : "alert",  // alert(알림) | mark(req 클래스 마킹) | all(알림+마킹). 기본 alert
        checkType    : "single", // single(첫 실패 즉시 중단·개별 알림) | multi(전건 수집 후 취합 알림). 기본 single
        focus        : true,     // 실패 항목 포커스 이동 여부. 기본 true
        editMode     : true,     // (그리드) 실패 셀 포커스 시 편집모드 진입 여부. 기본 true
        fields : {
            // 기본 규칙 — 필수/문자/길이
            ipbName    : { required : true, maxLength : 10, name : "사원명" },
            ipbAge     : { required : true, num : "n", fromNum : 1, toNum : 150, name : "나이" },
            ipbCode    : { allowChar : "0-9A-Z", ignoreChar : "#", fixLength : 8, name : "코드" },
            ipbRemark  : { minLength : 5, maxLength : 100, name : "비고" },

            // byte·자릿수 규칙 — 한/영 혼합 byte 제한, 정수.소수 자리수
            ipbCorpNm  : { required : true, maxLengthB : 80, name : "발행기관명" },      // 한글 40자/영문 80자
            ipbRate    : { num : "f", maxLengthF : "10.2", name : "수수료율" },          // 정수 10자리.소수 2자리

            // format 규칙 — email/phone/mobilePhone/date/birth/securityNumber/bizNum/corpNum/urlNoProtocol
            ipbEmail   : { required : true, format : "email", name : "이메일" },
            ipbBizNo   : { format : "bizNum", name : "사업자등록번호" },                 // 10자리+검증번호
            ipbCorpNo  : { format : "corpNum", name : "법인등록번호" },                  // 13자리+검증번호
            ipbHomeUrl : { format : "urlNoProtocol", name : "홈페이지" },                // http:// 등 포함 금지

            // 조건부 규칙 — 참조 컴포넌트 값으로 판정 (equals|notEquals|in|notEmpty, message 재정의 가능)
            ipbZipCd   : { emptyIf : { compID : "sbx_nation", notEquals : "410",
                                       message : "외국국적은 우편번호를 입력할 수 없습니다." }, name : "우편번호" },
            calChgDt1  : { requiredIf : { compID : "ipb_chgNm2", notEmpty : true,
                                          message : "상호변경내역1 변경일을 먼저 입력해주세요." }, name : "변경일1" },

            // 그룹 중복·체크박스 규칙
            sbxMonth1  : { duplicateGroup : "settleMonth", name : "결산월1" },           // 같은 그룹명 간 중복 금지
            sbxMonth2  : { duplicateGroup : "settleMonth", name : "결산월2" },
            chkAgree   : { checked : true, name : "개인정보 처리방침 동의" }             // 미체크("0"·false 포함) 실패
        }
    };

    // 폼 컨테이너 검증 (async — await 호출)
    const isValid = await $c.validate.validateDataCollect(grp_form, options);
    if (!isValid) return;

    // 그리드 검증 — fields 키는 컬럼ID, duplicate 로 행 간 중복 금지
    const isGridValid = await $c.validate.validateDataCollect(grd_list, {
        validateType : "all", checkType : "multi",
        fields : {
            SETTLE_MONTH : { required : true, duplicate : true, name : "결산월" },
            EMAIL        : { format : "email", name : "이메일" }
        }
    });

    입력 허용 문자, 입력 허용 불가 문자, 최대 입력 문자수 설정은 GridView의 Column의 속성에서 설정한다. <br/>
    - required:true - 필수 입력 항목 여부 <br/>
    - allowChar:0-9 - 숫자만 입력(정수형) <br/>
    - allowChar:0-9. - 숫자만 입력(실수형) <br/>
    - ignoreChar:a-zA-Z - 입력 허용 불가 문자 <br/>
    - minLength:10 - 최소 입력 문자수 <br/>
    - maxLength:15 - 최대 입력 문자수 <br/>
    - fixLength:13 - 고정 입력 문자수 <br/>
    - minLengthB:20 - 최소 입력 byte 수 <br/>
    - maxLengthB:50 - 최대 입력 byte 수 <br/>
    - maxLengthF:10.2 - 최대 입력 정수 + 소수점 자리수(,제외)<br/>
    - num:n - 숫자(0-9만) <br/>
    - num:i - 정수(음수 부호 허용) <br/>
    - num:f - 실수(부호·소수점 허용) <br/>
    - fromNum:5 - 최소 입력 숫자 <br/>
    - toNum:10 - 최대 입력 숫자 <br/>
    - format:email - email format <br/>
    - format:date - date format <br/>
    - format:phone - phone format <br/>
    - format:mobilePhone - mobilePhone format <br/>
    - format:bizNum - 사업자번호 format (10자리+검증번호) <br/>
    - format:corpNum - 법인등록번호 format (13자리+검증번호) <br/>
    - format:urlNoProtocol - URL에 프로토콜(http:// 등) 포함 금지 <br/>
    - format:birth - 생년월일(주민번호 앞자리) format <br/>
    - checked:true - 체크박스 필수 체크(약관 동의 등 — 빈 값·"0"·false·"N" 모두 실패) <br/>
    - emptyIf:{compID, equals|notEquals|in|notEmpty, message} - 참조 컴포넌트 조건 충족 시 입력 금지 <br/>
      (예: 국가코드가 대한민국(410)이 아니면 외국국적으로 판단해 입력 금지 —
      emptyIf : { compID : "sbx_nation", notEquals : "410", message : "외국국적은 우편번호를 입력할 수 없습니다." }) <br/>
    - requiredIf:{compID, equals|notEquals|in|notEmpty, message} - 참조 컴포넌트 조건 충족 시 필수 입력 <br/>
      (예: requiredIf : { compID : "ipb_chgNm2", notEmpty : true, message : "상호변경내역1 변경일을 먼저 입력해주세요." }) <br/>
    - duplicate:true - (그리드) 컬럼 값 행 간 중복 금지 <br/>
    - duplicateGroup:"그룹명" - (폼) 같은 그룹명을 지정한 필드 간 값 중복 금지 (예: 결산월1~n) <br/>

    ※ ignoreChar·byte 길이·num·범위·format 추가분·emptyIf·duplicate 계열 규칙은
    빈 값을 통과시킨다(필수 항목은 required 또는 requiredIf 병행 지정). checked 는 빈 값도 실패.
 */
scwin.validateDataCollect = async function (validateObj, options) {
    options = Object.assign({ validateType : "alert", checkType : "single", focus : true, editMode : true, fields : {} }, options);
    const fields = options.fields || {};

    if ($c.util.isEmpty(validateObj) || $c.util.isEmpty(fields)) return false;

    validateObj = (typeof validateObj === "string") ? $p.getComponentById(validateObj) : validateObj;
    if ($c.util.isEmpty(validateObj)) return false;

    const validateType = options.validateType.toUpperCase();
    const checkType = options.checkType.toUpperCase();
    const isGrid = (validateObj.getPluginName().toUpperCase() === "GRIDVIEW");

    // 컴포넌트 ID 추출 (getID 우선, 없으면 .id)
    const getCompId = function (comp) {
        return (typeof comp.getOriginalID === "function") ? comp.getOriginalID() : comp.id;
    };

    let validateResult = true;
    let messageArr = [];
    let firstObj = null;

    if (!isGrid) {
        let objArr = [];

        try {
            // 컴포넌트 수집도 try 내부에서 수행 — 실패 시 catch 로 false 반환
            objArr = scwin.getChildrenComponent(validateObj, {
                includePlugin: "autoComplete checkbox checkcombobox input inputCalendar radio selectbox searchbox secret textarea",
                recursive: true,
            });

            // req class 초기화 - 현재 미리 req class를 적용한 상태로 사용하기 때문에 초기화 코드는 사용하지 않음
            objArr.forEach(obj => {
                if (typeof obj.removeClass !== "undefined") {
                    //obj.removeClass("req");
                }
            });

			let isBreak = false;

            // options.fields(컴포넌트ID 또는 컬럼ID 기준) 규칙으로 validation 진행
            objArr.some(valObj => {
				if (isBreak) return true;

                const dataObjInfo = scwin.getDataCollection(valObj);
                if ($c.util.isEmpty(dataObjInfo)) return;

                const rules = fields[getCompId(valObj)] || fields[dataObjInfo.columnId];
                if ($c.util.isEmpty(rules)) return;

                const valInfo = Object.assign({ id : getCompId(valObj), name : undefined }, rules);

                for (const key of Object.keys(valInfo)) {
                    if (key === "id" || key === "name") continue;
                    const validateKey = key.toUpperCase();
                    const val = String(valInfo[key]);
                    if (!val) continue;

                    const result = scwin.validateDataGroup(validateKey, val, valInfo, valObj, dataObjInfo, checkType, validateType, options);
                    validateResult = (validateResult) ? result.validateResult : false;
                    messageArr.push(...result.messageArr);
                    (firstObj === null) && (firstObj = result.firstObj);

                    if (checkType === "SINGLE" && !validateResult) {
						isBreak = true;
						break;
					}
                }
            });

            // 전체 validate 메시지 출력
            if (!validateResult && (validateType === "ALERT" || validateType === "ALL") && checkType === "MULTI") {
                const message = messageArr.map(msg => `<p class="txt_hyphen">${msg}</p>`).join("");
                const height = 223 + ((messageArr.length > 4) ? (messageArr.length - 3) * 21 : 0);
                $c.win.alert(message, function() {
                    if (options.focus) firstObj?.focus();
                }, { disableCloseButton : false, height : height, width : 400 });
            } else if (!validateResult) {
                //if (options.focus) firstObj?.focus();
            }

        } catch (ex) {
            // finally 의 return 이 catch 의 return 을 덮어쓰지 않도록 finally 에서는 반환하지 않는다 (예외 시 항상 false)
            console.error(ex);
            return false;
        } finally {
            objArr = null;
        }
        return validateResult;
    } else {
        try {
            const gridViewCollect = await scwin.getGridViewDataList(validateObj);
            const gridViewData = gridViewCollect.getAllJSON();

			let isBreak = false;

            // GridView row × column, options.fields(컬럼ID 기준) 규칙으로 validation 진행
            gridViewData.some((rowData, rowIndex) => {
				if (isBreak) return true;

                Object.keys(rowData).some((columnId, colIndex) => {
					if (isBreak) return true;

                    const rules = fields[columnId];
                    if ($c.util.isEmpty(rules)) return;

                    const valInfo = Object.assign({ id : columnId, name : undefined }, rules);

                    for (const key of Object.keys(valInfo)) {
                        if (key === "id" || key === "name") continue;
                        const validateKey = key.toUpperCase();
                        const val = String(valInfo[key]);
                        if (!val) continue;

                        const result = scwin.validateDataCollection(validateKey, val, valInfo, validateObj, gridViewCollect, rowIndex, colIndex, checkType, validateType, options);
                        validateResult = (validateResult) ? result.validateResult : false;
                        messageArr.push(...result.messageArr);
                        (firstObj === null) && (firstObj = result.firstObj);

                        if (checkType === "SINGLE" && !validateResult) {
							isBreak = true;
							break;
						}
                    }
                });
            });

            // 전체 validate 메시지 출력
            if (!validateResult && (validateType === "ALERT" || validateType === "ALL") && checkType === "MULTI") {
                const message = messageArr.map(msg => `<p class="txt_hyphen">${msg}</p>`).join("");
                const height = 223 + ((messageArr.length > 4) ? (messageArr.length - 3) * 21 : 0);
                $c.win.alert(message, function() {
                    if (options.focus) firstObj?.focus();
                }, { disableCloseButton : false, height : height, width : 400 });
            } else if (!validateResult) {
                if (options.focus) firstObj?.focus();
            }

        } catch (ex) {
            // finally 의 return 이 catch 의 return 을 덮어쓰지 않도록 별도 finally 없이 반환한다 (예외 시 항상 false)
            console.error(ex);
            return false;
        }
        return validateResult;
    }
};

/**
 * @method
 * @name validateDataGroup
 * @description 데이터 유효성 확인
 * @param {string} validateKey validate key 값
 * @param {string} val validate key value 값
 * @param {string} valInfo validate 정보 값
 * @param {string} valObj component 객체
 * @param {string} dataObjInfo dataCollection 객체
 * @param {string} checkType validate check 방식 (SINGLE, MULTI)
 * @param {string} validateType validate 처리 방식 (ALERT, MARK, ALL)
 * @param {object} options validate 옵션
 * @returns {object} 데이터 유효성 검증 결과 ({ validateResult, messageArr, firstObj })
 * @hidden N
 * @exception
 * @example
 */
scwin.validateDataGroup = function (validateKey, val, valInfo, valObj, dataObjInfo, checkType, validateType, options) {
    let validateResult = true;
    let messageArr = [];
    let firstObj = null;
    const valObjValue = valObj.getValue();

    if (validateKey === "REQUIRED" && val.toUpperCase() === "TRUE") {
        if (valObjValue === "") {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 필수 입력사항입니다.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        }
    }

    if (validateKey === "ALLOWCHAR") {
        if (valObjValue.length !== ((valObjValue.match(new RegExp("[" + val + "]", "g")) === null) ? 0 : valObjValue.match(new RegExp("[" + val + "]", "g")).length)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 허용된 문자(${val})만 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        }
    }

    if (validateKey === "FORMAT") {
        if (val.toUpperCase() === "BIRTH" && !scwin.isBirthDay(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 생년월일을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        } else if (val.toUpperCase() === "DATE" && !scwin.isValidDate(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 날짜 형식을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        } else if (val.toUpperCase() === "MOBILEPHONE" && !$c.str.isMobilePhone(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 모바일폰 형식을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false, width : 400 });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        } else if (val.toUpperCase() === "PHONE" && !$c.str.isPhone(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 전화번호 형식을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false, width : 400 });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        } else if (val.toUpperCase() === "SECURITYNUMBER" && !$c.str.isSSN(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 주민등록번호 형식을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        } else if (val.toUpperCase() === "EMAIL" && !$c.str.isEmail(valObjValue)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 정확한 이메일 형식을 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
                        if (options.focus) scwin.setFocus(valObj);
                    }, { disableCloseButton : false });
                } else {
                    messageArr.push(msg);
                }
            }

            if (validateType === "MARK" || validateType === "ALL") {
                (firstObj === null) && (firstObj = valObj);
                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        }
    }

    if (validateKey === "FIXLENGTH") {
