                valObj.addClass("req");
                if (options.focus) scwin.setFocus(valObj);
            }

            validateResult = false;
        }
    }

    if (validateKey === "MINLENGTH") {
        if (valObjValue.length < Number.parseInt(val)) {
            if (validateType === "ALERT" || validateType === "ALL") {
                let msg = `${$c.str.attachPostposition(valInfo.name || dataObjInfo.columnName)} 최소길이(${val}) 보다 크게 입력해주세요.`;
                (firstObj === null) && (firstObj = valObj);

                if (checkType === "SINGLE") {
                    $c.win.alert(msg, function() {
